#define PI 3.14159265359

vec2 rotate2D(vec2 _st, float _angle){
    _st -= 0.5;
    _st *= mat2(cos(_angle),-sin(_angle), sin(_angle),cos(_angle));
    _st += 0.5;
    return _st;
}

vec2 tile(vec2 _st, float _zoom){
    _st *= _zoom;
    return fract(_st);
}

float box(vec2 _st, vec2 _size){
    _size = vec2(0.5)-_size*0.5;
    vec2 uv = step(_size,_st);
    uv *= step(_size,vec2(1.0)-_st);
    return uv.x*uv.y;
}

float border(vec2 st, float w) {
    vec2 lb = step(w,st);
    vec2 tr = step(w,1.0-st);
    return 1.0-lb.x*lb.y*tr.x*tr.y;
}

float mainStripes(vec2 st, float color, float i) {
    const vec2 MAIN_WIDTH = vec2(0.075,2.0);
    const float OPACITY = 0.3;

    color -= box(st, MAIN_WIDTH) * OPACITY * i;
    color -= box(st+vec2(0.15,0.0), MAIN_WIDTH) * OPACITY * i;
    color -= box(st+vec2(-0.15,0.0), MAIN_WIDTH) * OPACITY * i;
    color += box(st+vec2(-0.075,0.0), MAIN_WIDTH) * OPACITY * i;
    color += box(st+vec2(0.075,0.0), MAIN_WIDTH) * OPACITY * i;

    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 st = fragCoord.xy/iResolution.y;
    st += iTime*0.05;

    const vec3 RED = vec3(1.0,0.5,0.5);
    const float RED_WIDTH = 0.03;

    st = rotate2D(st,PI*0.09);
    st = tile(st, 4.0);
    vec2 stR90 = rotate2D(st, PI*0.5);

    float redStripe = border(st, RED_WIDTH);

    float main = 0.75;
    main -= redStripe;
    main = mainStripes(st, main, 0.8);
    main = mainStripes(stR90, main, 1.2);

    vec3 color = vec3(redStripe)*RED;
    color += vec3(main);
    fragColor = vec4(color,1.0);
}
